"""Pre-sell listing skeletons for the first 10 trade SKUs: Amazon (Listings Items / category flat-file columns) and eBay (Seller Hub bulk CSV columns).
Prices = UK list bench x 0.90 (trade) for the price list, marketplace price = bench x 0.95 incl. VAT shown ex-VAT basis noted. Lead time 10-14 days (pre-sell).
Usage: python3 generate_trade_listings.py -> out/amazon_listings.csv, out/ebay_listings.csv, out/trade_price_list.md"""
import csv, os
SKUS = [  # sku, title, bullets, bench_ex_vat, landed, uom, keywords, ebay_category_hint, amazon_type_hint
 ("EL-NICD-48-18","Emergency Lighting Battery 4.8V 1.8Ah NiCd Stick, 4 x Sub-C, Flying Leads", ["4.8V 1.8Ah NiCd stick for emergency lighting luminaires","High-temperature cells, flying leads, 1 year warranty","Replaces B980/315 style packs","Supplied with Batteries Regulations take-back scheme"], 12.19, 3.88, "each", "emergency lighting battery 4.8v nicd stick", "Business, Office & Industrial > Electrical & Test Equipment > Batteries", "Electronics > Batteries"),
 ("SPD-T2-1PN","Type 2 Surge Protection Device 1P+N, DIN Rail, BS EN 61643-11, 20kA In / 40kA Imax", ["Type 2 SPD for consumer units and distribution boards","Tested to BS EN 61643-11, CE and UKCA marked, English instructions","Uc 275V, In 20kA, Imax 40kA, Up <=1.5kV","Replaceable plug-in module with status indicator"], 18.90, 4.40, "each", "type 2 surge protection device din rail", "Business, Office & Industrial > Electrical > Circuit Breakers & Disconnectors", "Industrial Electrical"),
 ("ER-58-4FT-SET","Copper Bonded Earth Rod 5/8in x 4ft with Driving Stud and Clamp, BS EN 62561-2", ["5/8in (14.2mm) x 1.2m copper-bonded steel rod, 250 micron copper","Threaded with driving stud and rod clamp included","Tested to BS EN 62561-2; BS 7430 earthing","Pack of 1 set; pallet pricing for 50+"], 17.00, 4.90, "set", "earth rod 5/8 4ft copper bonded clamp", "Business, Office & Industrial > Electrical > Cable & Wire Management", "Industrial Electrical"),
 ("VRLA-12V-7AH","12V 7Ah VRLA Sealed Lead Acid Battery, F1/F2 Terminals, UN2800 Non-Spillable", ["12V 7Ah AGM VRLA for alarm panels, UPS, emergency lighting and access control","Non-spillable (UN2800), CE/UKCA, 3-5 year design life","151 x 65 x 94mm, F1 (F2 option) terminals","Batteries Regulations take-back included"], 15.50, 5.00, "each", "12v 7ah battery alarm ups vrla", "Business, Office & Industrial > Electrical > Batteries", "Electronics > Batteries"),
 ("LBL-WARN-25","Electrical Warning Label Pack of 25, BS 7671 Compliant, Danger 230V / Mixed Set", ["25 self-adhesive vinyl labels for consumer units and enclosures","Wording per BS 7671 section 514 (current amendment)","Weatherproof, UV stable, 5-year outdoor","Mixed pack: Danger 230V, Isolate before, RCD test, PV, Circuit chart"], 8.10, 0.97, "pack", "electrical warning labels pack consumer unit", "Business, Office & Industrial > Facility Maintenance & Safety > Signs", "Industrial & Scientific"),
 ("GLD-SWA-BW20","SWA Cable Gland Pack BW20, Brass, Indoor, with Shroud and Earth Tag, Pack of 2", ["BW20 brass glands for 20mm SWA, indoor use","Includes locknut, earth tag and PVC shroud","Manufactured to BS EN 62444","Pack of 2; CW20 outdoor version also available"], 4.10, 2.22, "pack", "swa gland pack bw20 brass", "Business, Office & Industrial > Electrical > Cable & Wire Management", "Industrial Electrical"),
 ("JK-RESIN-S1","LV Resin Cable Joint Kit, Straight, 1.5-6mm2 SWA, BS EN 50393", ["Straight-through resin joint for 1.5-6mm2 armoured cable","Two-part resin, connectors, instructions, CLP-labelled","Type tested to BS EN 50393","Shelf life 24 months"], 12.60, 2.72, "each", "resin cable joint kit swa straight", "Business, Office & Industrial > Electrical > Connectors", "Industrial Electrical"),
 ("GEN-FK-PERK-1104","Generator Service Filter Kit for Perkins 1104 Series, Fuel/Oil/Air, Aftermarket", ["Aftermarket service kit: fuel filter, oil filter, air filter","Cross-referenced to OEM part numbers (listed in description); not OEM","Media tested to ISO 19438 / ISO 4548-12 / ISO 5011","Other engine kits available: ask with your engine serial"], 85.71, 13.00, "kit", "perkins 1104 service kit filters generator", "Business, Office & Industrial > Industrial Power Generators", "Automotive"),
 ("HYD-ADPT-RACK40","Hydraulic Adaptor Starter Rack, 40 Lines BSPP/JIC, Steel, with Rack and Labels", ["40 most-used BSPP reducers and JIC/ORFS swivels, 10 of each line","Pressure-rated steel, zinc plated, size and rating on each bin label","Supplied with a counter rack and reorder sheet","Consignment option for trade accounts"], 120.00, 60.00, "rack", "hydraulic adaptor rack bspp jic", "Business, Office & Industrial > Hydraulics, Pneumatics & Pumps > Hydraulics > Fittings", "Industrial & Scientific"),
 ("PAT-PASS-500","PAT Test PASS Labels, Roll of 500, Synthetic Vinyl, Writable, 50 x 25mm", ["Roll of 500 PASS labels, writable face for date/tester/next test","Synthetic vinyl with permanent adhesive; not thermal paper","Compatible with standard label guns and PAT test printers","Also available: FAIL, mixed rolls, custom-printed with your logo"], 13.50, 1.66, "roll", "pat test labels pass roll 500", "Business, Office & Industrial > Electrical & Test Equipment > Test Equipment Accessories", "Industrial & Scientific"),
]
os.makedirs("out", exist_ok=True)
amz=[]; ebay=[]; pl=["# Trade price list (ex VAT), 30-day account for approved trade customers, next-day delivery on stock lines, 10-14 day lead on pre-sell lines\n", "| SKU | Product | Trade price | Pack | Lead time |", "|---|---|---|---|---|"]
for sku,title,bul,bench,landed,uom,kw,ebcat,amzcat in SKUS:
    mkt=round(bench*0.95-0.01,2); trade=round(bench*0.90-0.01,2)
    desc=" ".join(bul)+" Dispatched from our UK 3PL. Pre-sell lead time 10-14 days on first orders; stock lines next day. Trade accounts and volume pricing available."
    amz.append({"sku":sku,"product-name":title[:200],"brand":"GrantEdison Trade","manufacturer":"see listing","item_type_keyword":amzcat,"bullet_point1":bul[0],"bullet_point2":bul[1],"bullet_point3":bul[2],"bullet_point4":bul[3],"product_description":desc,"standard_price":mkt,"quantity":50,"fulfillment_channel":"MFN","handling_time_days":12,"generic_keywords":kw,"business_price":trade,"quantity_price_type":"percent","quantity_lower_bound1":10,"quantity_price1":5,"condition_type":"New","main_image_url":"<SET>","product_id":"<EAN - buy GS1 or use brand exemption>","product_id_type":"EAN"})
    ebay.append({"*Action":"Add","CustomLabel":sku,"*Category":ebcat,"*Title":title[:80],"*Description":desc,"*ConditionID":1000,"*Format":"FixedPrice","*Duration":"GTC","*StartPrice":mkt,"*Quantity":50,"*Location":"UK","PicURL":"<SET>","*DispatchTimeMax":12,"ShippingProfileName":"UK 48h tracked","ReturnProfileName":"30 day returns","PaymentProfileName":"Managed payments","BestOfferEnabled":1,"Product:EAN":"<SET or Does not apply>"})
    pl.append(f"| {sku} | {title} | £{trade:.2f} | {uom} | 10-14 days (pre-sell) |")
for name,rows in [("amazon_listings.csv",amz),("ebay_listings.csv",ebay)]:
    with open(f"out/{name}","w",newline="") as f: w=csv.DictWriter(f, fieldnames=rows[0].keys()); w.writeheader(); w.writerows(rows)
open("out/trade_price_list.md","w").write("\n".join(pl)+"\n\nTerms: prices ex VAT; carriage paid over £150; 30-day account subject to references; pallet rates for earth rods and batteries on request.\n")
print("wrote", len(amz), "Amazon rows,", len(ebay), "eBay rows, price list")
for r in amz: print(f"  {r['sku']:18s} mkt £{r['standard_price']:7.2f}  trade £{r['business_price']:7.2f}")
